content.css:
.p6-matrix .p6-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
  min-width: 0;
  font-size: 11px;
  font-style: normal;
  font-weight: normal;
  line-height: 1.25;
}
.p6-matrix .p6-actions button {
  font: inherit;
  text-align: left;
  white-space: nowrap;
}
.p6-matrix .p6-actions .p6-copy-group {
  display: inline-flex;
  max-width: 100%;
}
.p6-matrix .p6-actions .p6-copy-main {
  position: relative;
  display: flex;
  min-width: 0;
}
.p6-matrix .p6-actions .p6-copy-feedback .p6-copy-caption {
  visibility: hidden;
}
.p6-matrix .p6-actions .p6-copy-view {
  border-radius: 2px 0 0 2px;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.p6-matrix .p6-actions .p6-copy-options {
  border-left: 0;
  border-radius: 0 2px 2px 0;
  flex: none;
}
.p6-matrix .p6-actions .p6-action-status {
  position: absolute;
  inset: 3px;
  pointer-events: none;
  display: flex;
  align-items: center;
  padding: 0 3px;
  overflow: hidden;
  white-space: nowrap;
  background: var(--p6-background);
  color: var(--p6-foreground);
}
.p6-matrix .p6-actions .p6-action-announcement {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  border: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
.p6-matrix .p6-actions-popup {
  position: absolute;
  z-index: 20;
  margin: 0;
  padding: 4px;
  overflow: auto;
  overscroll-behavior: contain;
  border: 1px solid var(--p6-foreground);
  border-radius: 2px;
  background: var(--p6-background);
  color: var(--p6-foreground);
  font-size: 11px;
  font-style: normal;
  font-weight: normal;
  line-height: 1.25;
  text-align: left;
}
.p6-matrix .p6-actions-popup button,
.p6-matrix .p6-actions-popup input,
.p6-matrix .p6-actions-popup label {
  font: inherit;
  color: inherit;
  text-align: left;
}
.p6-matrix .p6-actions-popup button {
  min-height: 23px;
  max-width: 100%;
  padding: 2px 6px;
  border: 1px solid var(--p6-grid-colour);
  border-radius: 2px;
  background: var(--p6-background);
  cursor: pointer;
}
.p6-matrix .p6-actions-popup button:disabled {
  cursor: default;
  opacity: 0.6;
}
.p6-matrix .p6-actions-popup button:hover:not(:disabled) {
  border-color: currentColor;
}
.p6-matrix .p6-actions-popup button:focus-visible,
.p6-matrix .p6-actions-popup input:focus-visible {
  outline: 2px solid var(--p6-focus-colour);
  outline-offset: -2px;
}
.p6-matrix .p6-actions-popup .p6-actions-heading {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  margin-bottom: 4px;
}
.p6-matrix .p6-actions-popup .p6-actions-heading > span {
  flex: 1 1 auto;
  min-width: 0;
  overflow-wrap: anywhere;
}
.p6-matrix .p6-actions-popup .p6-actions-back,
.p6-matrix .p6-actions-popup .p6-actions-close {
  flex: none;
  padding: 1px 6px;
}
.p6-matrix .p6-actions-popup .p6-action-panel {
  min-width: 0;
}
.p6-matrix .p6-actions-popup .p6-action-item {
  display: block;
  position: relative;
  width: 100%;
  min-width: 0;
  margin: 1px 0;
  padding-right: 20px;
  border-color: transparent;
  border-radius: 0;
  white-space: normal;
  overflow-wrap: anywhere;
}
.p6-matrix .p6-actions-popup .p6-action-item[aria-checked="true"]::after {
  content: '✓';
  position: absolute;
  right: 5px;
  top: 3px;
}
.p6-matrix .p6-actions-popup .p6-find-label {
  display: block;
  margin: 0 0 3px;
}
.p6-matrix .p6-actions-popup .p6-find-input {
  width: 100%;
  min-width: 0;
  min-height: 25px;
  padding: 3px 5px;
  border: 1px solid var(--p6-grid-colour);
  border-radius: 2px;
  background: var(--p6-background);
}
.p6-matrix .p6-actions-popup .p6-find-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 4px;
}
.p6-matrix .p6-actions-popup .p6-find-status,
.p6-matrix .p6-actions-popup .p6-loaded-notice,
.p6-matrix .p6-actions-popup .p6-columns-note {
  margin: 4px 0;
  overflow-wrap: anywhere;
}
.p6-matrix .p6-actions-popup .p6-loaded-notice {
  border-top: 1px solid var(--p6-grid-colour);
  padding-top: 4px;
}
.p6-matrix .p6-actions-popup .p6-columns-list {
  min-width: 0;
}
.p6-matrix .p6-actions-popup .p6-column-choice {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 3px;
  min-width: 0;
  margin: 2px 0;
}
.p6-matrix .p6-actions-popup .p6-column-visibility {
  display: flex;
  align-items: center;
  flex: 1 1 auto;
  gap: 4px;
  min-width: 0;
  margin: 0;
}
.p6-matrix .p6-actions-popup .p6-column-visibility input {
  flex: none;
  margin: 0;
  accent-color: var(--p6-foreground);
}
.p6-matrix .p6-actions-popup .p6-column-visibility span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.p6-matrix .p6-actions-popup .p6-column-up,
.p6-matrix .p6-actions-popup .p6-column-down {
  flex: none;
  padding: 2px 5px;
}
.p6-matrix {
  --p6-grid-colour: #dedede;
  --p6-focus-colour: #252525;
  --p6-background: #ffffff;
  --p6-foreground: #222222;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  font-size: 11px;
  background: var(--p6-background);
  color: var(--p6-foreground);
}
.p6-matrix *,
.p6-matrix *::before,
.p6-matrix *::after {
  box-sizing: border-box;
}
.p6-matrix [hidden] {
  display: none !important;
}
.p6-matrix button,
.p6-matrix select {
  font: inherit;
  color: inherit;
}
.p6-matrix button:focus-visible,
.p6-matrix select:focus-visible,
.p6-matrix [tabindex]:focus-visible {
  outline: 2px solid var(--p6-focus-colour);
  outline-offset: -2px;
}
.p6-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
  flex: none;
  min-height: 30px;
  padding: 3px 5px;
  border-bottom: 1px solid var(--p6-grid-colour);
}
.p6-toolbar button,
.p6-toolbar select {
  min-height: 23px;
  border: 1px solid var(--p6-grid-colour);
  border-radius: 2px;
  background: var(--p6-background);
  padding: 2px 6px;
}
.p6-toolbar button {
  cursor: pointer;
}
.p6-toolbar button:disabled {
  cursor: default;
  opacity: 0.6;
}
.p6-hierarchy-toggle {
  white-space: nowrap;
}
.p6-hierarchy-toggle[aria-pressed="true"] {
  border-color: var(--p6-foreground);
}
.p6-expand-label {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}
.p6-expand-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
}
.p6-matrix .p6-toolbar {
  font-size: 11px;
  font-style: normal;
  font-weight: normal;
  line-height: 1.25;
}
.p6-matrix .p6-toolbar button,
.p6-matrix .p6-toolbar .p6-expand-label,
.p6-matrix .p6-toolbar .p6-expand-level {
  font: inherit;
}
.p6-matrix .p6-toolbar .p6-expand-level {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 7px;
  text-align: left;
}
.p6-matrix .p6-toolbar .p6-level-value {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.p6-matrix .p6-toolbar .p6-level-caret {
  flex: none;
}
.p6-matrix .p6-level-popup {
  position: absolute;
  z-index: 10;
  margin: 0;
  padding: 1px;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  border: 1px solid var(--p6-foreground);
  border-radius: 2px;
  background: var(--p6-background);
  color: var(--p6-foreground);
  font-size: 11px;
  font-style: normal;
  font-weight: normal;
  line-height: 1.25;
  text-align: left;
}
.p6-matrix .p6-level-popup .p6-level-option {
  position: relative;
  min-height: 23px;
  margin: 0;
  padding: 4px 18px 4px 6px;
  border: 1px solid transparent;
  font: inherit;
  text-align: left;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: pointer;
}
.p6-matrix .p6-level-popup .p6-level-option[aria-selected="true"]::after {
  content: '✓';
  position: absolute;
  right: 4px;
}
.p6-matrix .p6-level-popup .p6-level-option:hover {
  border-color: currentColor;
}
.p6-matrix .p6-level-popup .p6-level-active {
  color: var(--p6-background);
  background: var(--p6-foreground);
  border-color: var(--p6-foreground);
}
.p6-row-count {
  margin-left: auto;
  padding: 0 3px;
  white-space: nowrap;
}
.p6-notice {
  flex: none;
  padding: 5px 7px;
  border-bottom: 1px solid var(--p6-grid-colour);
  font-size: 11px;
  line-height: 1.35;
}
.p6-viewport {
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}
.p6-scroller {
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  overflow: auto;
  position: relative;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}
.p6-surface {
  position: relative;
}
.p6-header {
  position: sticky;
  top: 0;
  z-index: 5;
  border-bottom: 1px solid var(--p6-grid-colour);
  background: var(--p6-background);
  box-shadow: 0 -2px 0 var(--p6-background);
}
.p6-header-cell {
  position: absolute;
  top: 0;
  height: 100%;
  padding: 5px 12px 5px 6px;
  overflow: hidden;
  white-space: nowrap;
  line-height: 1.25;
  border-right: 1px solid var(--p6-grid-colour);
  text-overflow: ellipsis;
}
.p6-header-label {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
}
.p6-sort-button {
  display: block;
  width: 100%;
  height: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: inherit;
  white-space: inherit;
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: pointer;
}
.p6-resizer {
  position: absolute;
  top: 0;
  right: 0;
  width: 7px;
  height: 100%;
  cursor: col-resize;
  touch-action: none;
}
.p6-resizer:hover {
  border-right: 2px solid var(--p6-focus-colour);
}
.p6-body {
  position: relative;
}
.p6-row {
  position: absolute;
  left: 0;
  overflow: clip;
}
.p6-cell {
  position: absolute;
  top: 0;
  height: 100%;
  padding-left: 6px;
  padding-right: 6px;
  overflow: hidden;
  line-height: 1.25;
  white-space: nowrap;
  text-overflow: ellipsis;
  cursor: default;
  background-image: none, none;
  background-clip: padding-box, border-box;
}
.p6-matrix:not(.p6-high-contrast) .p6-row.p6-hovered:not(.p6-selected) > .p6-cell {
  background-image: linear-gradient(rgba(0, 0, 0, 0.1), rgba(0, 0, 0, 0.1)), none;
}
.p6-matrix:not(.p6-high-contrast) .p6-row.p6-selected > .p6-cell {
  background-image: linear-gradient(var(--p6-selection-shade), var(--p6-selection-shade)), none;
}
.p6-frozen-label {
  position: sticky;
  left: 0 !important;
  z-index: 2;
}
.p6-header .p6-frozen-label {
  z-index: 6;
}
.p6-label-cell {
  display: flex;
  align-items: center;
  gap: 4px;
}
.p6-label-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.p6-toggle {
  flex: none;
  min-width: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid currentColor;
  border-radius: 1px;
  font: inherit;
  line-height: 1;
  background: transparent;
  cursor: pointer;
}
.p6-toggle-spacer {
  display: inline-block;
  flex: none;
}
.p6-wrap {
  white-space: normal;
  overflow-wrap: anywhere;
}
.p6-label-cell.p6-wrap .p6-label-text {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.p6-value-cell.p6-wrap {
  white-space: pre-wrap;
}
.p6-horizontal-line {
  border-bottom: 1px solid var(--p6-grid-colour);
}
.p6-vertical-line {
  border-right: 1px solid var(--p6-grid-colour);
}
.p6-row-decorations {
  position: absolute;
  overflow: hidden;
  contain: strict;
  z-index: 4;
  pointer-events: none;
}
.p6-row-decoration {
  position: absolute;
  left: 1px;
  width: calc(100% - 2px);
  border: 1px solid currentColor;
  pointer-events: none;
}
.p6-row-decoration.p6-decoration-found {
  border: 1px dashed var(--p6-focus-colour);
}
.p6-row-decoration.p6-decoration-keyboard:not(.p6-decoration-found):not(.p6-decoration-selected) {
  border: 1px dotted currentColor;
}
.p6-row-decoration.p6-decoration-selected {
  border: 1px solid var(--p6-focus-colour);
  box-shadow: none;
}
.p6-matrix .p6-cell:focus-visible {
  outline: none;
  box-shadow: none;
}
.p6-matrix .p6-cell:focus-visible::after {
  content: '';
  position: absolute;
  top: 1px;
  right: 3px;
  bottom: 3px;
  left: 2px;
  border: 1px solid currentColor;
  pointer-events: none;
}
.p6-matrix .p6-cell.p6-narrow-cell:focus-visible::after {
  left: 0;
  right: 0;
  top: 2px;
  border: 0;
  border-top: 1px solid currentColor;
}
.p6-matrix .p6-cell.p6-tiny-cell:focus-visible::after {
  display: none;
}
.p6-highlighted {
  text-decoration: underline;
  text-decoration-thickness: 2px;
  text-underline-offset: 2px;
}
.p6-empty {
  position: absolute;
  inset: 70px 12px auto;
  padding: 10px;
  pointer-events: none;
}
.p6-resizing {
  cursor: col-resize;
  user-select: none;
}
.p6-high-contrast .p6-toggle,
.p6-high-contrast .p6-toolbar button,
.p6-high-contrast .p6-toolbar select {
  border-color: var(--p6-foreground);
}
.p6-high-contrast .p6-row-decoration.p6-decoration-hovered:not(.p6-decoration-selected):not(.p6-decoration-found) {
  border: 1px dotted var(--p6-foreground);
}
.p6-high-contrast .p6-row-decoration.p6-decoration-found {
  border: 1px dashed var(--p6-foreground);
}
.p6-high-contrast .p6-row-decoration.p6-decoration-selected {
  border: 1px solid var(--p6-foreground);
  box-shadow: none;
}
